const http = require('http');

const entries = [];

function sendJson(res, status, payload) {
  res.statusCode = status;
  res.setHeader('content-type', 'application/json');
  res.end(JSON.stringify(payload));
}

function readBody(req, cb) {
  let body = '';
  req.on('data', (c) => { body += c; });
  req.on('end', () => cb(body));
  req.on('error', () => sendJson(res_400(req), 400, { error: 'read error' }));
}

// Parse one entry payload; return {entry} or {error}.
function parseEntry(raw) {
  let data;
  try {
    data = JSON.parse(raw || '{}');
  } catch {
    return { error: 'invalid JSON body' };
  }
  const amount = Number(data.amount);
  if (!Number.isFinite(amount) || amount <= 0) {
    return { error: 'amount must be a positive number' };
  }
  const category = typeof data.category === 'string' && data.category.trim()
    ? data.category.trim().toLowerCase()
    : 'general';
  const note = typeof data.note === 'string' ? data.note : '';
  return { entry: { id: entries.length + 1, amount, note, category, ts: Date.now() } };
}

function summary() {
  const byCategory = {};
  let total = 0;
  for (const e of entries) {
    total += e.amount;
    const c = byCategory[e.category] || (byCategory[e.category] = { count: 0, total: 0 });
    c.count += 1;
    c.total += e.amount;
  }
  // Round to cents to avoid float drift in the aggregate view.
  for (const c of Object.values(byCategory)) c.total = Math.round(c.total * 100) / 100;
  return { count: entries.length, total: Math.round(total * 100) / 100, byCategory };
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (url.pathname === '/entries') {
    if (req.method === 'POST') {
      readBody(req, (body) => {
        const { entry, error } = parseEntry(body);
        if (error) { sendJson(res, 400, { error }); return; }
        entries.push(entry);
        sendJson(res, 201, entry);
      });
      return;
    }
    if (req.method === 'GET') {
      const category = url.searchParams.get('category');
      const list = category
        ? entries.filter((e) => e.category === category.trim().toLowerCase())
        : entries;
      sendJson(res, 200, list);
      return;
    }
    sendJson(res, 405, { error: 'method not allowed' });
    return;
  }
  if (url.pathname === '/summary' && req.method === 'GET') {
    sendJson(res, 200, summary());
    return;
  }
  sendJson(res, 404, { error: 'not found' });
});

const PORT = Number(process.env.PORT) || 3000;
if (require.main === module) {
  server.listen(PORT, () => {
    console.log(`mini-ledger listening on http://localhost:${PORT}`);
  });
}

module.exports = server;

